#!/usr/bin/env bash
# ─────────────────────────────────────────────────────────────────────────────
# Публикация отчёта о падении проверок.
#
# Вызывается из workflow «Проверки»:
#
#   bash .github/ci-report.sh "Датасет" examples.log flashcards.log
#
# Первый аргумент — заголовок, остальные — файлы с выводом упавших шагов.
#
# ── Куда уходит отчёт ───────────────────────────────────────────────────────
# Если задан PR_NUMBER — комментарием в сам pull request: разработка идёт с
# телефона, и логи Actions там читаются по десять символов в строку. Отчёт должен
# лежать там, куда человек и так смотрит.
#
# На main номера PR нет, поэтому отчёт уходит в Issue с меткой ci-failure. Иссью
# ОДИН на все падения: повторные прогоны добавляют комментарий, а не плодят
# тикеты. Тот же приём, что у E2E-прогона (см. e2e.yml) — и по той же причине.
#
# ── Выжимка идёт ПЕРЕД логом ────────────────────────────────────────────────
# Первая версия отчёта показывала только хвост лога, и этого не хватило: у
# node --test в конце стоит сводка «pass 303, fail 9», а имена упавших тестов
# остаются выше, за границей обрезки. Читать отчёт, из которого не видно, ЧТО
# упало, — то же самое, что читать «проверка не прошла».
#
# Поэтому сверху собираются строки-приговоры: «not ok» у тестов и строки с
# крестом у проверок датасета. Хвост лога остаётся ниже — в нём контекст.
#
# ── Почему tail, а не весь лог ──────────────────────────────────────────────
# Целиком лог не влезет в комментарий (у GitHub предел 65 536 символов), а
# обрезка с начала выбросила бы как раз итог.
# ─────────────────────────────────────────────────────────────────────────────
set -euo pipefail

title="${1:?нужен заголовок отчёта}"
shift

report=ci-report.md

# Сколько строк выжимки и хвоста показываем. Выжимка длиннее хвоста намеренно:
# двадцать упавших тестов важнее двадцати строк контекста.
SUMMARY_LINES=40
TAIL_LINES=60

{
  printf '## %s: проверка не прошла\n\n' "$title"

  # grep -h: без имён файлов, они и так видны ниже. Пустой результат — не повод
  # падать (set -e), отсюда `|| true`.
  summary=$(grep -hE '^not ok |❌|Error:|AssertionError' "$@" 2>/dev/null | head -n "$SUMMARY_LINES" || true)
  if [ -n "$summary" ]; then
    printf '### Что упало\n\n```\n%s\n```\n\n' "$summary"
  fi

  for log in "$@"; do
    # Шага могло не быть вовсе (предыдущий упал) — пустой файл пропускаем.
    [ -s "$log" ] || continue
    printf '<details><summary>Хвост <code>%s</code></summary>\n\n```\n' "$log"
    tail -n "$TAIL_LINES" "$log"
    printf '\n```\n\n</details>\n\n'
  done

  if [ -n "${RUN_URL:-}" ]; then
    printf '[Полный лог прогона](%s)\n' "$RUN_URL"
  fi
} > "$report"

# В лог job'а тоже: если публикация не удастся (нет прав на запись), отчёт всё
# равно должен остаться хотя бы здесь.
cat "$report"

if [ -n "${PR_NUMBER:-}" ]; then
  gh pr comment "$PR_NUMBER" --body-file "$report"
  exit 0
fi

gh label create ci-failure --color B60205 --description "Падения проверок" 2>/dev/null || true
existing=$(gh issue list --label ci-failure --state open --limit 1 --json number --jq '.[0].number // empty')

if [ -n "$existing" ]; then
  gh issue comment "$existing" --body-file "$report"
else
  gh issue create \
    --title "Проверки падают на main" \
    --label ci-failure \
    --body-file "$report"
fi
